import itertools
from collections import Counter

def anagram_lambda(str_list, target):
    """
    Finds all anagrams of a target string in a given list of strings.

    Args:
        str_list (list): A list of strings.
        target (str): The target string.

    Returns:
        list: A list of strings that are anagrams of the target string.
    """
    def count_anagrams(substring):
        """Counts the occurrences of each count of characters in a substring."""
        count_arr = [Counter(substring)]
        for i in range(1, len(substring) + 1):
            for subset in itertools.combinations(substring, i):
                if len(subset) == len(substring):
                    cleaned_subset = [char for char in subset if char.isalnum()]
                    len_subset = len(cleaned_subset)
                    count_arr.append(Counter(cleaned_subset))
        return count_arr

    anagrams = []
    for str in str_list:
        if str!= target:
            substrings = str.split()
            for submodule in Counter(substrings).most_common():
                sub_str = ''.join(submodule)
                count_arr = count_anagrams(sub_str)
                for count_tuple in (tuple(map(int, sub_str.split()[i].split(''))) for i in range(len(sub_str))):
                    if count_tuple in count_arr:
                        anagrams.extend([str for _, sub_str, _ in (count_tuple[1], (count_tuple,) * count_arr.index(count_tuple))])
    return sorted(set(anagrams))

