def add_dict(dict1, dict2):
    """
    Combines two dictionaries by adding values for common keys.

    Args:
        dict1 (dict): The first dictionary to combine.
        dict2 (dict): The second dictionary to combine.

    Returns:
        dict: A new dictionary with the combined values.
    """
    # Create a new dictionary to store the combined result
    combined_dict = {}

    # Copy keys from the first dictionary to the combined dictionary
    for key in dict1:
        combined_dict[key] = dict1[key]

    # Update the combined dictionary with values from the second dictionary
    # If a key is already present in the combined dictionary, its value will be updated
    for key, value in dict2.items():
