def super_seq(str1, str2, len_str1, len_str2):
    """
    Finds the length of the shortest string that has both str1 and str2 as subsequences.

    Args:
    str1 (str): The first string.
    str2 (str): The second string.
    len_str1 (int): The length of str1.
    len_str2 (int): The length of str2.

    Returns:
    int: The length of the shortest string that has both str1 and str2 as subsequences.
    """
    def construct_seq(i=0, j=0, memo=None):
        # Base case: If we have processed both strings, return the current sequence length.
        if memo is None:
            memo = {}

        # If both strings are fully processed, return 1 if they are equal, 2 otherwise.
        if i == len_str1 and j == len_str2 and str1[i:i+len_str1] == str2[j:j+len_str2]:
            return 1 if str1[i:i+len_str1] == str2[j:j+len_str2] else 2
        # If both strings are fully processed or have been previously constructed, return the memoed value.
        if (i, j, i+len_str1-1, j+len_str2-1) in memo:
            return memo[(i, j, i+len_str1-1, j+len_str2-1)]

        # If we haven't processed both strings yet, recursively construct the sequences and store the results.
        result = 0
        if i < len_str1:
            # Check if the substring from index i to (j-1) of str1 can be a prefix of both str2 and subsequence_len_str1 of str2.
            prefix_length = construct_seq(i+1, j, memo).bit_length()
            result = maxLength(result, prefix_length, len_str1, j, str2)
        if j < len_str2:
            # Check if the substring from index (i-1) of str2 to (j) of str2 can be a prefix of both str1 and subsequence_len_str2 of str1.
            prefix_length = construct_seq(i, j+1, memo).bit_length()
            result = maxLength(result, prefix_length, i, str1, str2)

        # Store the result of the recursive call and return it.
        memo[(i, j, i+len_str1-1, j+len_str2-1)] = result
        return result

    def maxLength(result, prefix_length, current_str1, current_str2, prefix_str):
        # Updates the result for the current parse tree.
        if prefix_length == len(str2):
            return len(prefix_str)
        if current_str1 and result >= len(str1) + len(prefix_str) - 1:
            return len(str1)
        return maxLength(result, (prefix_length if prefix_str else 0) + 1, current_str1, current_str2, prefix_str1 + prefix_str2)

    return construct_seq()

