def unique_sublists(lst):
    """
    This function takes a list of lists as input and returns a dictionary where each key is a tuple representing
    a unique sublist and the corresponding value is the count of such sublists.

    :param lst: A list of lists
    :return: A dictionary where each key is a tuple representing a unique sublist and the corresponding value is the count of such sublists
    """
    unique_sublist_counts = {}
    for sublists in lst:
        for sublist in sublists:
            if tuple(sublist) not in unique_sublist_counts:
                unique_sublist_counts[tuple(sublist)] = 0
            unique_sublist_counts[tuple(sublist)] += 1
    return unique_sublist_counts


