def find_first_occurrence(arr, x):
    left, right = 0, len(arr) - 1

    # Perform binary search
    while left <= right:
        mid = left + (right - left) // 2

        if arr[mid] < x:
            left = mid + 1
        elif arr[mid] > x:
            right = mid - 1
        else:
            # Check if it's the first occurrence
            if mid == 0 or arr[mid - 1] < x:
                return mid
            else:
                right = mid - 1

    return -1  # x is not present in the array
