def find_first_occurrence(arr, x):
    # Use binary search to find the leftmost occurrence of x
    left_index = -1 * find_leftmost_match(arr, x)
    # If leftmost index is not found, use binary search to find the rightmost occurrence
    right_index = -1 * find_rightmost_match(arr, x)
    return left_index * 2 + (1 if right_index != -1 else 0)

def find_leftmost_match(arr, x):
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] < x:
            left = mid + 1
        else:
            right = mid - 1
    return left

def find_rightmost_match(arr, x):
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] - x:
            left = mid + 1
        else:
            right = mid - 1
    return left

