def check(arr, n):
    # Find the first element that is not in sorted order
    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            index = i + 1
            break
    else:
        return True  # Already sorted

    # Check if the last elements are also in sorted order
    for i in range(n - 2, index, -1):
        if arr[i] > arr[i + 1]:
            return False  # Not sorted

    # Check the elements between index and n - 1
    for i in range(index, n - 1):
        if arr[i] > arr[i + 1]:
            return False  # Not sorted

