def previous_palindrome(number):
    # Convert the number to a string to facilitate easy manipulation
    number_str = str(number)
    # Check if the number is a palindrome
    if number_str == number_str[::-1]:
        # If it's a palindrome, decrement the number, convert back to int, and return it
        return int(number_str[:-1]) if number_str[:-1] else 1
    else:
        # If it's not a palindrome, decrement the entire number (convert back to str and mod by 1)
        number_str = str(int(number_str[:-1]))
        # Iterate decrementing by 1 until a palindrome is found
        while not number_str == number_str[::-1]:
            number_str = str(int(number_str) - 1)
        return int(number_str)
