def Sum_of_Inverse_Divisors(n, m):
    # count the number of divisors
    def count_divisors(num):
        count = 0
        for i in range(1, int(num ** 0.5) + 1):
            if num % i == 0:
                if i == num // i:
                    count += i
                else:
                    count += i + num // i
        return count

    # find the number of divisors that are common to both m and n
    def common_divisors(num1, num2):
        cnt1 = 0
        cnt2 = 0
        for i in range(1, int(num1 ** 0.5) + 1):
            if num1 % i == 0:
                cnt1 += 1
                if i == num1 // i:
                    cnt1 -= 1
        for i in range(1, int(num2 ** 0.5) + 1):
            if num2 % i == 0:
                cnt2 += 1
                if i == num2 // i:
                    cnt2 -= 1

        result = []
        for i in range(1, min(cnt1, cnt2) + 1):
            # add common divisors to the list
            if cnt1 > i and cnt2 > i:
                if cnt1 % 2 == 0 and cnt2 % 2 == 0:
                    if i * 4 <= cnt1 and i * 4 <= cnt2:
                        result.append(i * 4)
                if cnt1 % 2 != 0 and cnt2 % 2 != 0:
                    if i * 4 <= cnt2:
                        result.append(i * 4)
                if cnt1 % 2 == 0 and cnt2 % 2 != 0:
                    if i * 4 <= cnt2 and 2 * i <= cnt1:
                        result.append(i * 4)
                if cnt1 % 2 != 0 and cnt2 % 2 == 0:
                    if i * 4 <= cnt1 and 2 * i <= cnt2:
                        result.append(i * 4)

        if cnt1 > cnt2:
            return result
        else:
            result.reverse()
            return result


    # calculate the sum of inverse of divisors
    def sum_of_inverses(divisors, multiplier):
        total = 0
        for divisor in divisors:
            total += 1 / multiplier**divisor
        return total


    # calculate the number of common divisors
    num_common_divisors = common_divisors(n, m)
    # calculate the sum of counter
    inversions_sum = sum_of_inverses(num_common_divisors, n)

    return inversions_sum

