def gcd(a, b):
    """Calculate the greatest common divisor of a and b."""
    while b:
        a, b = b, a % b
    return a

def gcd_sum_in_range(nums, bound):
    """Find the largest subset where each pair is divisible."""
    largest_subset_size = 0
    largest_subset = set()

    for num in nums:
        can_form_good_pair_count = num < bound // num
        if can_form_good_pair_count:
            subset_size_addition, highest_gcd = 0, num
            while True:
                highest_gcd -= 1
                if highest_gcd == num:
                    break
                gcd_result = gcd(num, highest_gcd)
                if gcd_result == num:
                    subset_size_addition += 1
                elif gcd_result < bound // highest_gcd:
                    largest_subset_size += subset_size_addition
                    break
                else:
                    subset_size_addition += min(subset_size_addition, 2)

    largest_subset_size += max([(num % bound == 0) for num in nums]).count(True)
    return largest_subset_size

