def maxAverageOfPath(S, m):
    n = len(S)
    dp = [[float('-inf')] * n for _ in range(m + 1)]

    # Base case: the average is the same as the sum when there's only one row or column
    dp[1] = S[0]

    # Compute the maximum average for each row
    for i in range(1, m + 1):
        maximum = float('-inf')
        for j in range(i):
            total = 0
            for k in range(i):
                total += S[k][j]
            average = total / i
            maximum = max(maximum, average)
        dp[i] = maximum

    # Compute the maximum average path from the bottom-left to the top-right
    return max(accumulate(dp, initial=0)[:-1])

# Helper function to use with the max function
def accumulate(iterable, fn=operator.add, initial=None):
    it = iter(iterable)
    try:
        total = next(it)
    except StopIteration:
        return initial
    return fn(total, accumulate(it, fn, initial))
