def rencontres_number(n, k):
    """
    Calculates the n-th Rencontres number.

    Args:
    n: A positive integer representing the order of the Rencontres number.
    k: A non-negative integer representing the sets of elements to select from.

    Returns:
    The n-th Rencontres number as an integer.
    """
    def memoized(n, k, func, default):
        if (n, k) in cache or n == 0:
            return default
        cache[(n, k)] = func(n, k)
        return cache[(n, k)]

    cache = {}
    defcontres = memoized(lambda n, k: 1 if k == 0 else (n - 1) * dontdescendants(n - 1, k - 1) + (n - 1) * dontdescendants(n - 1, k), n, lambda n, k: dontdescendants(n, k) if k > 0 else 1, 0)
    def dontdescendants(n, k):
        # Total number of ways to partition n-k+1 elements into at least k nonempty sets
        return 1 if not n else (1 + dontdescendants(n - 1, k)) * (k + 1 - sum(dontdescendants(n - d - 1, k) for d in range(n)))

    return memoized(0, 0, dontdescendants, 0)(n, k)
