def rgb_to_hsv(r, g, b):
    # Convert RGB to HLS
    h, l, s = rgb_hls(r, g, b)

    # Convert HLS to HSV
    v, h2, s2 = hls_to_hsv(l, s)

    return h, (v), (h2), (s2)

def rgb_hls(r, g, b):
    min_val = min(r, g, b)
    max_val = max(r, g, b)
    diff = max_val - min_val

    l = (max_val + min_val) / 2

    if max_val == min_val:
        h = 0
    elif max_val == r:
        h = (60 * ((g - b) / diff) + 360) % 360
    elif max_val == g:
        h = (60 * ((b - r) / diff) + 120) % 360
    elif max_val == b:
        h = (60 * ((r - g) / diff) + 240) % 360

    if max_val == 0:
        s = 0
    else:
        s = (diff / max_val) * 100

    return h, l, s

def hls_to_hsv(l, s):
    v = 1 - abs(2 * l - 1)
    if v == 0:
        return None, None, None

    if s == 0:
        h = None
    else:    
        if v == l:  # achromatic
            h = 0
        else:  
            h = 60 * ((s / v) * 6)

    return v, h, s
