def remove_nested(t):
    """
    Takes a tuple and returns a new tuple with all nested tuples removed.
    Example usage:
    remove_nested((1, 5, 7, (4, 6), 10)) returns (1, 5, 7, 10)
    """

    def remove(nested_tuple):
        for item in nested_tuple:
            if isinstance(item, tuple):
                yield from remove(item)
            else:
                yield item

    return tuple(remove(t))

