def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def Sum(n):
    """Find the sum of all prime divisors of a given number."""
    prime_sum = 0
    for i in range(2, n + 1):
        if n % i == 0 and is_prime(i):
            prime_sum += i
    return prime_sum
