def Sum(n):
    """
    This function calculates the sum of all prime divisors of a given number.

    Args:
        n (int): The input number.

    Returns:
        int: The sum of all prime divisors of the input number.
    """

    def is_prime(num):
        """Helper function to check if a number is prime."""
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    prime_divisors = []
    for i in range(2, n + 1):
        if n % i == 0 and is_prime(i):
            prime_divisors.append(i)
    return sum(prime_divisors)

