def find_Digits(n):
    """
    Counts the number of digits in the factorial of a given number.

    Args:
        n (int): The input number.

    Returns:
        int: The number of digits in the factorial of n.
    """
    def factorial(x):
        """Calculates the factorial of a given number."""
        if x == 0:
            return 1
        else:
            return x * factorial(x-1)

    if n == 0 or n == 1:
        return 1
    else:
        factorials = [factorial(i) for i in range(n, 1, -1)]
        return len(str(factorials[-1]))


