def divisible_by_digits(n, limit):
    result = []
    for i in range(1, limit + 1):
        str_i = str(i)
        divisors = []
        for digit in str_i:
            if digit!= '0' and i % int(digit) == 0:
                divisors.append(int(digit))
        if divisors:
            result.extend(i for i in range(n, limit + 1) if i % (1 + *divisors) == 0)
    return result

