def previous_palindrome(n):
    """
    This function finds the previous palindrome of a specified number.

    Args:
        n (int): The input number.

    Returns:
        int: The previous palindrome of the input number.
    """
    def is_palindrome(num):
        """Helper function to check if a number is a palindrome."""
        return str(num) == str(num)[::-1]

    def prev_palindrome_num(num):
        """Helper function to find the previous palindrome of a number."""
        if num < 0:
            return 0
        for i in range(num - 1, -1, -1):
            if is_palindrome(i):
                return i
        return None

    return prev_palindrome_num(n)
