    # Calculate the discriminant
    d = b**2 - 4*a*c

    # If the discriminant is zero, the roots are equal
    if d == 0:
        root = -b / (2*a)
        if math.isclose(root, 1/math.root(b**2+4*a*c))) :
            return "Yes"
        else:
            return "No"
    else:
        sqrt_d = math.sqrt(d)
        root1 = (-b + sqrt_d) / (2*a)
        root2 = (-b - sqrt_d) / (2*a)
        if math.isclose(root1, 1/root2) or math.isclose(root2, 1/root1):
            return "Yes"
        else:
            return "No"

print(Check_Solution(2,0,2))  # Output: Yes
