def largest_subset(numbers, div):
    def Division(num):
        for i in range(1, num + 1):
            if num % i == 0:
                return i
        return num

    numbers.sort()
    subset_size = len(numbers)
    n = subset_size
    largest_subset_size = 1
    largest_subset_size_index = 0

    for i in range(n):
        current_divide = Division(numbers[i])
        if current_divide > div:
            break
        if i > largest_subset_size_index:
            largest_subset_size_index += 1
            largest_subset_size -= 1
            if largest_subset_size == 0:
                return i

    return largest_subset_size
