def largest_subset(nums, limit):
    def dfs(index):
        if index == len(nums):
            return True
        subset_size = 0
        for i in range(index, len(nums)):
            if nums[i] % limit == 0:
                subset_size += 1
                if dfs(i + 1):
                    return True
        return False

    low, high = 0, len(nums)
    while low < high:
        mid = (low + high) // 2
        if dfs(mid):
            high = mid
        else:
            low = mid + 1
    return low

print(largest_subset([1, 3, 6, 13, 17, 18], 6))  # Output: 4
