def count_duplic(nums):
    """
    Counts the frequency of consecutive duplicate elements in a given list of numbers.

    Args:
        nums (list): A list of numbers.

    Returns:
        tuple: A tuple of two lists. The first list contains the indices of duplicate elements,
               and the second list contains the duplicate elements themselves.
    """
    duplicates = []
    result = {}

    for i, num in enumerate(nums):
        if num in result:
            result[num].append(i)
        else:
            result[num] = [i]

    unique_nums = []
    for num, indices in result.items():
        if len(indices) > 1:
            duplicates.append(num)
            for i in indices[1:]:
                unique_nums.append(num)

    return duplicates, unique_nums

