def max_chain_length(pairs, k):
    n = len(pairs)
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, min(i, k) + 1):
            if j == 1:
                dp[i][j] = 0
            else:
                dp[i][j] = 1 + dp[i - 1][j - 1]

    max_length = 0
    for i in range(1, n + 1):
        for j in range(1, min(i, k) + 1):
            if j == 1:
                max_length = max(max_length, dp[i][j])
            else:
                max_length = max(max_length, dp[i - 1][j - 1])

