def count_Fac(n):
    # Check if n is a prime number
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    # Find all prime factors of n
    factors = [i for i in range(2, n + 1) if is_prime(i)]

    # Count distinct power of prime factors
    count = 0
    for factor in factors:
        while n % factor == 0:
            count += 1
            n //= factor

    return count

# Test the function
