def Sum_of_Inverse_Divisors(n):
    def is_divisor(d, p):
        return d % p == 0

    def inverse_divisor(d):
        return 1 / d if d != 1 else -1  # Handle 1 (cleverly as reciprocal doesn't depend on 1)

    sum_inverse = 0
    for i in range(2, n+1):
        if is_divisor(n, i):
            sum_inverse += inverse_divisor(i)

    return sum_inverse

assert Sum_of_Inverse_Divisors(6, 12) == 2
```

