def Sum_of_Inverse_Divisors(n):
    # This function calculates the sum of the inverses of the divisors of n
    compensating_factorial = [1] * (n+1)
    for i in range(1, n+1):
        compensating_factorial[i] = compensating_factorial[i-1] * (1 / i)

    return sum(compensating_factorial)

# The test assert ensures the expected output for given input
assert Sum_of_Inverse_Divisors(6,12) == 2
