def find_Index(n):
    def is_triangular(num):
        if num < 1:
            return False
        for i in range(1, int(num ** 0.5) + 1):
            if num % i == 0:
                break
        return True

    def find_smallest_triangular(n):
        res = n  # Use n as the starting index
        while True:
            curr_num = int(f"{}.{}'.format(str(n), int(n ** 0.5) + 1))
            if is_triangular(curr_num) and res == curr_num:
                return res
            res += 1

    return find_smallest_triangular(n)

