    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def Sum(n):
    sum_of_primes = 0
    for i in range(2, n + 1):
        if is_prime(i) and n % i == 0:
            sum_of_primes += i
    return sum_of_primes
