from typing import List, Tuple

class Pair:
    def __init__(self, start: int, end: int):
        self.start = start
        self.end = end

def max_chain_length(pairs: List[Pair], n: int) -> int:
    pairs.sort(key=lambda x: x.end)
    dp = [1] * n
    for i in range(n):
        for j in range(i):
            if pairs[i].start > pairs[j].end:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)
```

