from typing import List, Tuple

class Pair:
    def __init__(self, start: int, end: int):
        self.start = start
        self.end = end

def max_chain_length(pair_list: List[Pair], k: int) -> int:
    def find_chain_length(start: int) -> int:
        dp = [0] * (k + 1)
        for pair in pair_list:
            for i in range(min(k, pair.end), pair.start - 1, -1):
                dp[i] = max(dp[i], dp[i - pair.end] + 1)
        return dp[k]

    return max(find_chain_length(start) for start in range(1, k + 1) if start < pair_list[-1].start)

# Example usage
pair_list = [Pair(5, 24), Pair(15, 25), Pair(27, 40), Pair(50, 60)]
k = 4
print(max_chain_length(pair_list, k))  # Output: 3
