def max_chain_length(pairs, n):
    pairs.sort(key=lambda x: x.end)  # Sort pairs by end value
    dp = [1] * n  # Initialize DP array with 1s

    for i in range(1, n):
        for j in range(i):
            if pairs[i].start > pairs[j].end:  # Current pair starts after the previous one
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)
