class Pair:
    def __init__(self, start, end):
        self.start = start
        self.end = end

def max_chain_length(pairs, n):
    pairs.sort(key=lambda x: x.end)  # Sort pairs based on end value in descending order
    dp = [1] * n  # DP array to store the length of the longest chain ending at each pair

    for i in range(n):
        for j in range(i):
            if pairs[i].start >= pairs[j].end:  # Check if the current pair can be added to the chain
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)  # Return the length of the longest chain
```

