def count_Fac(n):
    count = 0
    prime_factors = []

    # Find all prime factors of n
    for i in range(2, int(n**0.5) + 1):
        while (n % i == 0):
            prime_factors.append(i)
            n = n // i

    # Check remaining factors are prime
    if n > 1:
        prime_factors.append(n)

    # Count unique prime factors
    unique_factors = list(set(prime_factors))
    return len(unique_factors)
