def count_Fac(n):
    count = 0
    for i in range(2, n+1):
        prime = True
        for j in range(2, i):
            if i % j == 0:
                prime = False
                break
        if prime:
            distinct_factors = set()
            for j in range(2, int(i**0.5) + 1):
                if i % j == 0:
                    distinct_factors.add(j)
                    if i // j != j:
                        distinct_factors.add(i // j)
            count += len(distinct_factors)
    return count
