def maxAverageOfPath(matrix, n):
    total_sum = 0
    path_sum = 0
    for i in range(n):
        for j in range(n):
            total_sum += matrix[i][j]
    num_paths = n * n
    avg = total_sum / num_paths
    for i in range(n):
        for j in range(i, n):
            path_sum += matrix[i][j] + matrix[j][i]
            avg = max(avg, path_sum / (n + 1))
            path_sum -= matrix[j][i]
    for j in range(n):
