def super_seq(str1, str2, len1, len2):
    # Create a 2D array to store the lengths of the longest common subsequence
    dp = [[0] * (len2 + 1) for _ in range(len1 + 1)]

    # Fill the dp array
    for i in range(1, len1 + 1):
        for j in range(1, len2 + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # The length of the longest common subsequence is dp[len1][len2]
    lcs_length = dp[len1][len2]

    # The length of the shortest super sequence is len1 + len2 - lcs_length
    return len1 + len2 - lcs_length
