def find_triplet_array(arr, target_sum, desired_sum):
    arr.sort()
    n = len(arr)
    for i in range(n - 2):
        left, right = i + 1, n - 1
        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]
            if current_sum == desired_sum:
                return (arr[i], arr[left], arr[right])
            elif current_sum < desired_sum:
                left += 1
            else:
                right -= 1
    return None
