def find_first_occurrence(arr, number):
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = left + (right - left) // 2
        if arr[mid] < number:
            left = mid + 1
        elif arr[mid] > number:
            right = mid - 1
        else:
            if mid == 0 or arr[mid - 1] < number:
                return mid
            right = mid - 1
    return -1
```

